iris_df = pd.read_csv("/content/drive/MyDrive/dsml/Iris.csv")

iris_df

iris_df.describe()

iris_df.corr(numeric_only = True)

min_length = iris_df.SepalLengthCm.min()
max_length = iris_df.SepalLengthCm.max()

normal_length = (iris_df.SepalLengthCm - min_length) / (max_length - min_length)

normal_length

normal_length.plot.kde()

iris_df["SepalLengthCm"].plot.kde()

from sklearn.preprocessing import MinMaxScaler

minmax_scaler = MinMaxScaler(feature_range = (0,1))

norm_data = minmax_scaler.fit_transform(iris_df.drop("Species", axis = 1))

norm_data

#drawback  of normalization - outliers

# highly sensitive to outliers(biggest drawback)
# new data can change all values
# no robust for real world data

#advantage
# proportional spacing

# monotonicity (relative order of  value)

pd.DataFrame(norm_data , columns = ['Id','SepalLengthCm', 'SepalWidthCm', 'PetalLengthCm', 'PetalWidthCm'])

pd.DataFrame(norm_data , columns = ['Id','SepalLengthCm', 'SepalWidthCm', 'PetalLengthCm', 'PetalWidthCm']).describe()

#z score normalization

mean_length = iris_df.SepalLengthCm.mean()
std_length = iris_df.SepalLengthCm.std()

normal_z_length = (iris_df.SepalLengthCm - mean_length)/ std_length
normal_z_length

normal_z_length.plot.kde()

from sklearn.preprocessing import StandardScaler
st_scalar = StandardScaler()

from matplotlib import axes
norm_data = st_scalar.fit_transform(iris_df.drop("Species", axis = 1))

norm_data

pd.DataFrame(norm_data , columns = ['Id','SepalLengthCm', 'SepalWidthCm', 'PetalLengthCm', 'PetalWidthCm'])

