"""![image.png](data:image/png;base64,)

Power Transformation

x_norm = sign(x) * abs(x) ** a
"""

power_factor = 0.7
normal_length = np.sign(iris_df.SepalLengthCm) * np.power(np.abs(iris_df.SepalLengthCm), power_factor)

normal_length

